package ru.neverland.archaeology.restoration;

import java.util.*;

/** Authoritative identities and consumption journal. Nothing in this model transfers money or an inventory. */
public final class RestorationBook {
    private RestorationBook(){}
    public static final int MAX_SOURCES=30_000,MAX_FRAGMENTS=30_000,MAX_OPERATIONS=30_000;
    public enum FragmentPhase { MAILBOX, CLAIMING, OWNED, RESERVED, SPENT }
    public enum Kind { CLAIM, RESTORE }
    public enum Phase { PREPARED, ARMED, COMPLETE, CANCELLED, REVIEW }
    static String text(String value,int max){if(value==null||value.isBlank()||value.length()>max||value.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Неверный текст реставрации");return value;}
    static String artifact(String id){text(id,64);if(!id.matches("[a-z0-9_-]{1,64}"))throw new IllegalArgumentException("Неверный тип артефакта");return id;}
    public record Recipe(String artifact,String rarity,int parts){public Recipe{artifact=RestorationBook.artifact(artifact);rarity=text(rarity,32);if(parts<3||parts>8)throw new IllegalArgumentException("Для реставрации нужно от 3 до 8 разных частей");}}
    public record Source(UUID id,String origin,UUID player,String playerName,long at,UUID fragment){public Source{Objects.requireNonNull(id);origin=text(origin,220);Objects.requireNonNull(player);playerName=text(playerName,64);if(at<0)throw new IllegalArgumentException("Неверное время находки");}}
    public record Fragment(UUID id,UUID source,UUID finder,String finderName,Recipe recipe,int part,long at,FragmentPhase phase,UUID operation){
        public Fragment{Objects.requireNonNull(id);Objects.requireNonNull(source);Objects.requireNonNull(finder);finderName=text(finderName,64);Objects.requireNonNull(recipe);Objects.requireNonNull(phase);if(part<1||part>recipe.parts()||at<0||(phase==FragmentPhase.CLAIMING||phase==FragmentPhase.RESERVED||phase==FragmentPhase.SPENT)!=(operation!=null))throw new IllegalArgumentException("Неверный фрагмент");}
        Fragment phase(FragmentPhase next,UUID op){return new Fragment(id,source,finder,finderName,recipe,part,at,next,op);}
    }
    public record Operation(UUID id,Kind kind,UUID player,String playerName,long at,Recipe recipe,List<UUID> fragments,UUID output,String item,Phase phase,String note){
        public Operation{Objects.requireNonNull(id);Objects.requireNonNull(kind);Objects.requireNonNull(player);playerName=text(playerName,64);Objects.requireNonNull(recipe);Objects.requireNonNull(output);fragments=List.copyOf(fragments);Objects.requireNonNull(phase);if(at<0||fragments.isEmpty()||fragments.size()>8||new HashSet<>(fragments).size()!=fragments.size()||kind==Kind.CLAIM&&fragments.size()!=1||kind==Kind.RESTORE&&fragments.size()!=recipe.parts())throw new IllegalArgumentException("Неверный набор фрагментов");item=text(item,128*1024);if(Base64.getDecoder().decode(item).length>64*1024)throw new IllegalArgumentException("Слишком большой предмет");note=text(note,300);}
        Operation phase(Phase next,String reason){return new Operation(id,kind,player,playerName,at,recipe,fragments,output,item,next,reason);}
        public boolean pending(){return phase==Phase.PREPARED||phase==Phase.ARMED||phase==Phase.REVIEW;}
    }
    public record State(Map<UUID,Source> sources,Map<UUID,Fragment> fragments,Map<UUID,Operation> operations,long revision){
        public State{sources=Map.copyOf(sources);fragments=Map.copyOf(fragments);operations=Map.copyOf(operations);if(revision<0||sources.size()>MAX_SOURCES||fragments.size()>MAX_FRAGMENTS||operations.size()>MAX_OPERATIONS)throw new IllegalArgumentException("Журнал реставрации заполнен");var origins=new HashSet<String>();var pending=new HashSet<UUID>();var outputs=new HashSet<UUID>();
            for(var e:sources.entrySet()){var s=e.getValue();if(!e.getKey().equals(s.id())||!origins.add(s.origin())||s.fragment()!=null&&!fragments.containsKey(s.fragment()))throw new IllegalArgumentException("Несогласованный источник фрагмента");}
            for(var e:fragments.entrySet()){var f=e.getValue();var source=sources.get(f.source());if(!e.getKey().equals(f.id())||source==null||!f.id().equals(source.fragment())||!f.finder().equals(source.player())||!f.finderName().equals(source.playerName())||f.at()!=source.at())throw new IllegalArgumentException("Фрагмент без подтверждённого источника");if(f.operation()!=null){var op=operations.get(f.operation());if(op==null||!op.fragments().contains(f.id()))throw new IllegalArgumentException("Расход фрагмента без исходной операции");}}
            long payloadChars=0;
            for(var e:operations.entrySet()){var op=e.getValue();payloadChars+=op.item().length();if(payloadChars>16*1024*1024)throw new IllegalArgumentException("Архив предметов реставрации заполнен; новые передачи приостановлены");boolean missing=false;for(UUID fragmentId:op.fragments())if(!fragments.containsKey(fragmentId))missing=true;if(!e.getKey().equals(op.id())||missing||op.pending()&&!pending.add(op.player())||op.kind()==Kind.RESTORE&&(!outputs.add(op.output())||fragments.containsKey(op.output())))throw new IllegalArgumentException("Повтор или неизвестная операция реставрации");
                for(UUID id:op.fragments()){var f=fragments.get(id);if(!f.recipe().equals(op.recipe()))throw new IllegalArgumentException("Изменён рецепт начатой реставрации");if(op.pending()&&(f.phase()!=(op.kind()==Kind.CLAIM?FragmentPhase.CLAIMING:FragmentPhase.RESERVED)||!op.id().equals(f.operation())))throw new IllegalArgumentException("Операция не обеспечена зарезервированными фрагментами");if(op.phase()==Phase.COMPLETE&&op.kind()==Kind.RESTORE&&(f.phase()!=FragmentPhase.SPENT||!op.id().equals(f.operation())))throw new IllegalArgumentException("Реставрация завершена без расхода точных частей");}
            }
        }
        public static State empty(){return new State(Map.of(),Map.of(),Map.of(),0);}
        private State next(Map<UUID,Source> sources,Map<UUID,Fragment> fragments,Map<UUID,Operation> operations){return new State(sources,fragments,operations,Math.incrementExact(revision));}
        public boolean blocked(UUID player){return operations.values().stream().anyMatch(op->op.player().equals(player)&&op.pending());}
        public long minted(UUID player,long now){long start=Math.max(0,now-86_400_000L);return sources.values().stream().filter(s->s.fragment()!=null&&s.at()>start&&(player==null||s.player().equals(player))).count();}
        public State discover(Source source,Fragment fragment){var old=sources.get(source.id());if(old!=null){if(!old.equals(source)||fragment!=null&&!fragment.equals(fragments.get(fragment.id())))throw new IllegalArgumentException("Источник уже рассмотрен; новый выбор запрещён");return this;}if((source.fragment()!=null)!=(fragment!=null))throw new IllegalArgumentException("Нет фрагмента находки");if(fragment!=null&&(fragment.phase()!=FragmentPhase.MAILBOX||fragment.operation()!=null))throw new IllegalArgumentException("Новая находка должна ждать получения");var nextSources=new HashMap<>(sources);nextSources.put(source.id(),source);var nextFragments=new HashMap<>(fragments);if(fragment!=null&&nextFragments.put(fragment.id(),fragment)!=null)throw new IllegalArgumentException("ID фрагмента уже существует");return next(nextSources,nextFragments,operations);}
        public State prepare(Operation operation){if(operation.phase()!=Phase.PREPARED||operations.containsKey(operation.id())||blocked(operation.player()))throw new IllegalArgumentException("Предыдущая операция ещё не завершена");var nextFragments=new HashMap<>(fragments);var parts=new HashSet<Integer>();
            for(UUID id:operation.fragments()){var f=fragments.get(id);if(f==null||!f.recipe().equals(operation.recipe()))throw new IllegalArgumentException("Фрагменты относятся к разным экземплярам рецепта");if(operation.kind()==Kind.CLAIM){if(f.phase()!=FragmentPhase.MAILBOX||!f.finder().equals(operation.player())||!operation.output().equals(f.id()))throw new IllegalArgumentException("Фрагмент недоступен для получения");nextFragments.put(id,f.phase(FragmentPhase.CLAIMING,operation.id()));}
                else{if(f.phase()!=FragmentPhase.OWNED||!parts.add(f.part()))throw new IllegalArgumentException("Нужны разные ещё не использованные части");nextFragments.put(id,f.phase(FragmentPhase.RESERVED,operation.id()));}}
            if(operation.kind()==Kind.RESTORE&&parts.size()!=operation.recipe().parts())throw new IllegalArgumentException("Неполный набор частей");var nextOperations=new HashMap<>(operations);nextOperations.put(operation.id(),operation);return next(sources,nextFragments,nextOperations);
        }
        public State arm(UUID id){var op=require(id);if(op.phase()==Phase.ARMED)return this;if(op.phase()!=Phase.PREPARED)throw new IllegalArgumentException("Операцию нельзя выполнять повторно");return replace(op.phase(Phase.ARMED,"Инвентарь разрешено изменить один раз"),fragments);}
        public State cancelPrepared(UUID id,String reason){var op=require(id);if(op.phase()!=Phase.PREPARED)throw new IllegalArgumentException("После начала изменения инвентаря нужна сверка; повторная выдача запрещена");var nextFragments=new HashMap<>(fragments);for(UUID fragment:op.fragments())nextFragments.put(fragment,fragments.get(fragment).phase(op.kind()==Kind.CLAIM?FragmentPhase.MAILBOX:FragmentPhase.OWNED,null));return replace(op.phase(Phase.CANCELLED,reason),nextFragments);}
        /** Caller must retain proof in this JVM that inventory application has not started; never use for restart recovery. */
        State cancelUntouched(UUID id,String reason){var op=require(id);if(op.phase()==Phase.PREPARED)return cancelPrepared(id,reason);if(op.phase()!=Phase.ARMED)throw new IllegalArgumentException("Нет безопасного подтверждения отсутствия передачи");var nextFragments=new HashMap<>(fragments);for(UUID fragment:op.fragments())nextFragments.put(fragment,fragments.get(fragment).phase(op.kind()==Kind.CLAIM?FragmentPhase.MAILBOX:FragmentPhase.OWNED,null));return replace(op.phase(Phase.CANCELLED,reason),nextFragments);}
        public State review(UUID id,String reason){var op=require(id);if(op.phase()==Phase.REVIEW)return this;if(op.phase()!=Phase.ARMED)throw new IllegalArgumentException("Нет неопределённой передачи");return replace(op.phase(Phase.REVIEW,reason),fragments);}
        public State complete(UUID id){var op=require(id);if(op.phase()==Phase.COMPLETE)return this;if(op.phase()!=Phase.ARMED&&op.phase()!=Phase.REVIEW)throw new IllegalArgumentException("Инвентарь ещё не передан");var nextFragments=new HashMap<>(fragments);for(UUID fragment:op.fragments())nextFragments.put(fragment,fragments.get(fragment).phase(op.kind()==Kind.CLAIM?FragmentPhase.OWNED:FragmentPhase.SPENT,op.kind()==Kind.CLAIM?null:op.id()));return replace(op.phase(Phase.COMPLETE,"Сохранение инвентаря подтверждено по ID операции"),nextFragments);}
        private Operation require(UUID id){var op=operations.get(id);if(op==null)throw new IllegalArgumentException("Операция не найдена");return op;}
        private State replace(Operation operation,Map<UUID,Fragment> nextFragments){var nextOperations=new HashMap<>(operations);nextOperations.put(operation.id(),operation);return next(sources,nextFragments,nextOperations);}
    }
}
